function numDecodings(s) {
  // BUG: no leading-zero guard, single-digit branch ignores '0',
  // and the two-digit branch accepts pairs outside 10..26.
  let prev2 = 1, prev1 = 1;
  for (let i = 2; i <= s.length; i++) {
    let cur = prev1;                       // always adds the single digit
    cur += prev2;                          // always adds the pair
    prev2 = prev1;
    prev1 = cur;
  }
  return prev1;
}
